from stone_shelter_assistant.search.document_content import build_embedding_text
from stone_shelter_assistant.search.document_models import KnowledgeSearchDocument
from stone_shelter_assistant.search.enums import DocumentKind
from stone_shelter_assistant.search.infrastructure import qdrant_collections, typesense_collections
from stone_shelter_assistant.search.knowledge.encyclopedia_document_builder import (
    build_encyclopedia_documents,
)
from stone_shelter_assistant.search.knowledge.stone_compatibility_document_builder import (
    build_stone_compatibility_documents,
)

ENCYCLOPEDIA_PATH: Final = Path("fixtures/knowledge/stone-encyclopedias/stone-encyclopedia_en.md")
COMPATIBILITY_PATH: Final = Path(
    "fixtures/knowledge/type-compatibility/stone-type-compatibility_en.json"
)


class KnowledgeIndexer:
    def __init__(
        self,
        project_root: Path,
        typesense: AsyncClient,
        qdrant: AsyncQdrantClient,
        embeddings: Embeddings,
        embedding_dimension: int,
    ) -> None:
        self._project_root = project_root
        self._typesense = typesense
        self._qdrant = qdrant
        self._embeddings = embeddings
        self._embedding_dimension = embedding_dimension

    async def reload_encyclopedia(self) -> int:
        documents = build_encyclopedia_documents(
            (self._project_root / ENCYCLOPEDIA_PATH).read_text(encoding="utf-8"),
            ENCYCLOPEDIA_PATH.as_posix(),
        )
        return await self._replace(documents, (DocumentKind.ENCYCLOPEDIA_SECTION,))

    async def reload_compatibility(self) -> int:
        documents = build_stone_compatibility_documents(
            (self._project_root / COMPATIBILITY_PATH).read_text(encoding="utf-8"),
            COMPATIBILITY_PATH.as_posix(),
        )
        return await self._replace(
            documents,
            (
                DocumentKind.COMPATIBILITY_PAIR,
                DocumentKind.COMPATIBILITY_TYPE_PORTRAIT,
                DocumentKind.COMPATIBILITY_READING_RULES,
            ),
        )

    async def _replace(
        self,
        documents: Sequence[KnowledgeSearchDocument],
        kinds: tuple[DocumentKind, ...],
    ) -> int:
        vectors = await self._embeddings.aembed_documents(
            [build_embedding_text(doc.title, doc.text) for doc in documents]
        )
        points = [
            models.PointStruct(
                id=str(doc.id),
                vector=vector,
                payload=doc.model_dump(mode="json", exclude={"id"}),
            )
            for doc, vector in zip(documents, vectors, strict=True)
        ]

        await typesense_collections.ensure_knowledge_collection(self._typesense)
        await qdrant_collections.ensure_knowledge_collection(
            self._qdrant, vector_size=self._embedding_dimension
        )
        typesense_documents = self._typesense.collections[
            typesense_collections.KNOWLEDGE_COLLECTION
        ].documents
        await typesense_documents.delete({"filter_by": f"document_kind:=[{','.join(kinds)}]"})
        await self._qdrant.delete(
            collection_name=qdrant_collections.KNOWLEDGE_COLLECTION,
            points_selector=models.FilterSelector(
                filter=models.Filter(
                    must=[
                        models.FieldCondition(
                            key="document_kind",
                            match=models.MatchAny(any=[kind.value for kind in kinds]),
                        )
                    ]
                )
            ),
            wait=True,
        )

        results = await typesense_documents.import_(
            [doc.model_dump(mode="json") for doc in documents], {"action": "upsert"}
        )
        for document, result in zip(documents, results, strict=True):
            if not result["success"]:
                raise RuntimeError(
                    f"Typesense rejected {document.source_key}: {result.get('error')}"
                )

        await self._qdrant.upsert(
            collection_name=qdrant_collections.KNOWLEDGE_COLLECTION,
            points=points,
            wait=True,
        )
        return len(documents)

"""Search the encyclopedia and compatibility guide."""

from langchain_core.embeddings import Embeddings
from qdrant_client import AsyncQdrantClient, models
from typesense import AsyncClient
from typesense.exceptions import ObjectNotFound

from stone_shelter_assistant.search.document_models import (
    DEFAULT_LANGUAGE,
    KNOWLEDGE_DOCUMENT_ADAPTER,
    CompatibilityPairSearchDocument,
    KnowledgeDocument,
    KnowledgeSearchFilters,
)
from stone_shelter_assistant.search.enums import CompatibilityVerdict, DocumentKind
from stone_shelter_assistant.search.infrastructure import qdrant_collections, typesense_collections
from stone_shelter_assistant.search.knowledge.stone_compatibility_document_builder import (
    build_pair_key,
)
from stone_shelter_assistant.stones.enums import StoneType


class KnowledgeSearchService:
    def __init__(
        self, typesense: AsyncClient, qdrant: AsyncQdrantClient, embeddings: Embeddings
    ) -> None:
        self._typesense = typesense
        self._qdrant = qdrant
        self._embeddings = embeddings

    async def search_lexical(
        self, query: str = "", filters: KnowledgeSearchFilters | None = None, limit: int = 5
    ) -> list[KnowledgeDocument]:
        return await self._search_lexical(query, _exact_matches(filters), limit)

    async def search_semantic(
        self, query: str, filters: KnowledgeSearchFilters | None = None, limit: int = 5
    ) -> list[KnowledgeDocument]:
        query = query.strip()
        if not query:
            raise ValueError("Semantic search requires a query")

        matches = _exact_matches(filters)
        result = await self._qdrant.query_points(
            collection_name=qdrant_collections.KNOWLEDGE_COLLECTION,
            query=await self._embeddings.aembed_query(query),
            query_filter=models.Filter(
                must=[
                    models.FieldCondition(key=field, match=models.MatchValue(value=value))
                    for field, value in matches
                ]
            )
            if matches
            else None,
            limit=limit,
            with_payload=True,
        )
        return [
            KNOWLEDGE_DOCUMENT_ADAPTER.validate_python({**(point.payload or {}), "id": point.id})
            for point in result.points
        ]

    async def get_compatibility_pair(
        self, first_type: StoneType, second_type: StoneType, language: str = DEFAULT_LANGUAGE
    ) -> CompatibilityPairSearchDocument | None:
        filters = KnowledgeSearchFilters(
            document_kind=DocumentKind.COMPATIBILITY_PAIR, language=language
        )
        matches = [*_exact_matches(filters), ("pair_key", build_pair_key(first_type, second_type))]
        documents = await self._search_lexical("", matches, limit=1)
        if not documents:
            return None
        pair = documents[0]
        if not isinstance(pair, CompatibilityPairSearchDocument):
            raise ValueError("Expected a compatibility pair document")
        return pair

    async def list_compatibility_pairs(
        self, stone_type: StoneType, verdict: CompatibilityVerdict, language: str = DEFAULT_LANGUAGE
    ) -> list[CompatibilityPairSearchDocument]:
        filters = KnowledgeSearchFilters(
            document_kind=DocumentKind.COMPATIBILITY_PAIR, stone_type=stone_type, language=language
        )
        documents = await self._search_lexical(
            "", [*_exact_matches(filters), ("verdict", verdict.value)], limit=len(StoneType)
        )
        return [doc for doc in documents if isinstance(doc, CompatibilityPairSearchDocument)]

    async def _search_lexical(
        self, query: str, matches: list[tuple[str, str]], limit: int
    ) -> list[KnowledgeDocument]:
        documents = self._typesense.collections[
            typesense_collections.KNOWLEDGE_COLLECTION
        ].documents
        try:
            result = await documents.search(
                {
                    "q": query.strip() or "*",
                    "query_by": "title,text",
                    "filter_by": " && ".join(f"{field}:=`{value}`" for field, value in matches),
                    "per_page": limit,
                }
            )
        except ObjectNotFound:
            # The knowledge collection is created by the first fixture reload.
            return []
        return [
            KNOWLEDGE_DOCUMENT_ADAPTER.validate_python(hit["document"])
            for hit in result.get("hits", [])
        ]


def _exact_matches(filters: KnowledgeSearchFilters | None) -> list[tuple[str, str]]:
    matches: list[tuple[str, str]] = []
    if filters is None:
        return matches
    if filters.document_kind is not None:
        matches.append(("document_kind", filters.document_kind.value))
    if filters.stone_type is not None:
        matches.append(("stone_types", filters.stone_type.value))
    if filters.language is not None:
        matches.append(("language", filters.language))
    return matches

"""Explicit HTTP operations for reloading the authored knowledge sources."""

from pathlib import Path
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException

from stone_shelter_assistant.dependencies import get_grounding_catalog, get_knowledge_indexer
from stone_shelter_assistant.search.knowledge.grounding_catalog import (
    GroundingCatalog,
    GroundingEntry,
)
from stone_shelter_assistant.search.knowledge.knowledge_indexer import KnowledgeIndexer

router = APIRouter(prefix="/api/v1/knowledge", tags=["knowledge"])


@router.post("/grounding/reload")
async def reload_grounding(
    catalog: Annotated[GroundingCatalog, Depends(get_grounding_catalog)],
) -> dict[str, object]:
    seed = Path("fixtures/knowledge/grounding") / f"grounding_{catalog.version}.json"
    snapshot = await catalog.reload(seed)
    return {
        "count": len(snapshot.entries),
        "content_hash": snapshot.content_hash,
        "catalog_version": snapshot.catalog_version,
    }


@router.get("/grounding/search")
async def search_grounding(
    q: str, catalog: Annotated[GroundingCatalog, Depends(get_grounding_catalog)]
) -> list[GroundingEntry]:
    return await catalog.search(q)


@router.put("/grounding/entries/{entry_id}")
async def update_grounding(
    entry_id: str,
    entry: GroundingEntry,
    catalog: Annotated[GroundingCatalog, Depends(get_grounding_catalog)],
) -> dict[str, object]:
    if entry_id != entry.id:
        raise HTTPException(status_code=422, detail="Entry ID does not match the path")
    try:
        snapshot = await catalog.upsert(entry)
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    return {"count": len(snapshot.entries), "content_hash": snapshot.content_hash}


@router.post("/encyclopedia/reindex")
async def reindex_encyclopedia(
    indexer: Annotated[KnowledgeIndexer, Depends(get_knowledge_indexer)],
) -> dict[str, int]:
    # NOTE: Learning-project happy path. Delete and reload without compatibility checks or rollback.
    return {"indexed_encyclopedia_documents": await indexer.reload_encyclopedia()}


@router.post("/compatibility/reindex")
async def reindex_compatibility(
    indexer: Annotated[KnowledgeIndexer, Depends(get_knowledge_indexer)],
) -> dict[str, int]:
    # NOTE: Learning-project happy path. Delete and reload without compatibility checks or rollback.
    return {"indexed_compatibility_documents": await indexer.reload_compatibility()}

