"""Search historical case event notes in the operational indexes."""

from langchain_core.embeddings import Embeddings
from qdrant_client import AsyncQdrantClient, models
from typesense import AsyncClient

from stone_shelter_assistant.search.document_content import to_unix_microseconds
from stone_shelter_assistant.search.document_models import CaseEventSearchDocument
from stone_shelter_assistant.search.enums import DocumentKind
from stone_shelter_assistant.search.infrastructure import qdrant_collections, typesense_collections
from stone_shelter_assistant.search.stones.search_contracts import CaseEventSearchFilters


class CaseEventSearchService:
    def __init__(
        self, typesense: AsyncClient, qdrant: AsyncQdrantClient, embeddings: Embeddings
    ) -> None:
        self._typesense = typesense
        self._qdrant = qdrant
        self._embeddings = embeddings

    async def search_lexical(
        self, query: str = "", filters: CaseEventSearchFilters | None = None, limit: int = 5
    ) -> list[CaseEventSearchDocument]:
        filters = filters or CaseEventSearchFilters()
        clauses = [f"{field}:=`{value}`" for field, value in _exact_matches(filters)]
        start, end = _timestamp_bounds(filters)
        if start is not None:
            clauses.append(f"occurred_at:>={start}")
        if end is not None:
            clauses.append(f"occurred_at:<{end}")

        documents = self._typesense.collections[
            typesense_collections.OPERATIONAL_COLLECTION
        ].documents
        result = await documents.search(
            {
                "q": query.strip() or "*",
                "query_by": "text",
                "filter_by": " && ".join(clauses),
                "per_page": limit,
            }
        )
        return [
            CaseEventSearchDocument.model_validate(hit["document"])
            for hit in result.get("hits", [])
        ]

    async def search_semantic(
        self, query: str, filters: CaseEventSearchFilters | None = None, limit: int = 5
    ) -> list[CaseEventSearchDocument]:
        query = query.strip()
        if not query:
            raise ValueError("Semantic search requires a query")

        filters = filters or CaseEventSearchFilters()
        conditions: list[models.Condition] = [
            models.FieldCondition(key=field, match=models.MatchValue(value=value))
            for field, value in _exact_matches(filters)
        ]
        start, end = _timestamp_bounds(filters)
        if start is not None or end is not None:
            conditions.append(
                models.FieldCondition(key="occurred_at", range=models.Range(gte=start, lt=end))
            )

        result = await self._qdrant.query_points(
            collection_name=qdrant_collections.OPERATIONAL_COLLECTION,
            query=await self._embeddings.aembed_query(query),
            query_filter=models.Filter(must=conditions),
            limit=limit,
            with_payload=True,
        )
        return [
            CaseEventSearchDocument.model_validate({**(point.payload or {}), "id": point.id})
            for point in result.points
        ]


def _exact_matches(filters: CaseEventSearchFilters) -> list[tuple[str, str]]:
    matches = [("document_kind", DocumentKind.CASE_EVENT.value)]
    if filters.stone_external_id is not None:
        matches.append(("stone_external_id", str(filters.stone_external_id)))
    if filters.event_type is not None:
        matches.append(("event_type", filters.event_type.value))
    return matches


def _timestamp_bounds(filters: CaseEventSearchFilters) -> tuple[int | None, int | None]:
    start = filters.occurred_from
    end = filters.occurred_before
    return (
        to_unix_microseconds(start) if start is not None else None,
        to_unix_microseconds(end) if end is not None else None,
    )

"""Build operational search documents from a stone, its profile, and its case."""

import json
from uuid import NAMESPACE_URL, uuid5

from stone_shelter_assistant.search.document_content import (
    build_embedding_text,
    calculate_text_hash,
    to_unix_microseconds,
)
from stone_shelter_assistant.search.document_models import (
    DEFAULT_LANGUAGE,
    PROJECTION_VERSION,
    SEARCH_SCHEMA_VERSION,
    CaseEventSearchDocument,
    StoneSearchDocument,
)
from stone_shelter_assistant.stones.models import (
    CaseEventModel,
    ShelterCaseModel,
    StoneModel,
    StoneProfileModel,
)


def build_stone_document(
    stone: StoneModel,
    case: ShelterCaseModel,
    profile: StoneProfileModel | None = None,
) -> StoneSearchDocument:
    """Build one stone card with its supplied profile and current case filters."""
    traits = sorted(profile.socialization_traits) if profile is not None else []
    care_level = profile.care_level if profile is not None else None
    text_blocks = []
    if biography := (stone.biography or "").strip():
        text_blocks.append(biography)
    if traits:
        labels = ", ".join(trait.replace("_", " ").lower() for trait in traits)
        text_blocks.append(f"Socialization: {labels}")
    if care_level is not None:
        text_blocks.append(f"Care level: {care_level.lower()}")
    if profile is not None:
        for label, value in (
            ("Health notes", profile.health_notes),
            ("Trigger notes", profile.trigger_notes),
            ("Preferred environment", profile.preferred_environment),
        ):
            if value and value.strip():
                text_blocks.append(f"{label}: {value.strip()}")

    text = "\n\n".join(text_blocks) or stone.name
    return StoneSearchDocument.model_validate(
        _document_fields(
            source_key=f"stone:{stone.external_id}",
            title=stone.name,
            text=text,
            source_data={
                "id": str(stone.id),
                **_stone_and_case_fields(stone, case),
                "stone_size": stone.stone_size,
                "adoption_status": case.adoption_status,
                "current_shelter_id": str(case.current_shelter_id),
                "socialization_traits": traits,
                "care_level": care_level,
            },
        )
    )


def build_case_event_document(
    stone: StoneModel,
    case: ShelterCaseModel,
    event: CaseEventModel,
) -> CaseEventSearchDocument:
    """Build one historical document with a stable ID derived from the source event."""
    source_key = f"case-event:{event.external_id}"
    event_label = event.event_type.replace("_", " ").capitalize()
    occurred_at = to_unix_microseconds(event.occurred_at)
    return CaseEventSearchDocument.model_validate(
        _document_fields(
            source_key=source_key,
            title=f"{stone.name} — {event_label}",
            text=event.event_notes,
            source_data={
                "id": str(
                    uuid5(
                        NAMESPACE_URL, f"urn:stone-shelter-assistant:search-document:{source_key}"
                    )
                ),
                **_stone_and_case_fields(stone, case),
                "event_external_id": str(event.external_id),
                "event_type": event.event_type,
                "occurred_at": occurred_at,
            },
        )
    )


def _stone_and_case_fields(stone: StoneModel, case: ShelterCaseModel) -> dict[str, str]:
    return {
        "stone_external_id": str(stone.external_id),
        "case_external_id": str(case.external_id),
        "case_number": case.case_number,
        "stone_type": stone.stone_type,
    }


def _document_fields(
    *,
    source_key: str,
    title: str,
    text: str,
    source_data: dict[str, str | int | list[str] | None],
) -> dict[str, object]:
    source_data = {**source_data, "title": title, "text": text}
    source_json = json.dumps(source_data, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return {
        **source_data,
        "language": DEFAULT_LANGUAGE,
        "source_key": source_key,
        "schema_version": SEARCH_SCHEMA_VERSION,
        "projection_version": PROJECTION_VERSION,
        "source_revision": calculate_text_hash(source_json),
        "content_hash": calculate_text_hash(build_embedding_text(title, text)),
    }

"""Read a registered stone once and project it into both search indexes."""

from uuid import UUID

from stone_shelter_assistant.search.document_models import (
    CaseEventSearchDocument,
    StoneSearchDocument,
)
from stone_shelter_assistant.search.stones.qdrant_indexer import QdrantStoneIndexer
from stone_shelter_assistant.search.stones.stone_document_builder import (
    build_case_event_document,
    build_stone_document,
)
from stone_shelter_assistant.search.stones.typesense_indexer import TypesenseStoneIndexer
from stone_shelter_assistant.stones.repository_protocols import (
    ShelterCaseRepository,
    StoneRepository,
)


class StoneIndexingService:
    def __init__(
        self,
        stone_repository: StoneRepository,
        shelter_case_repository: ShelterCaseRepository,
        typesense_indexer: TypesenseStoneIndexer,
        qdrant_indexer: QdrantStoneIndexer,
    ) -> None:
        self._stone_repository = stone_repository
        self._shelter_case_repository = shelter_case_repository
        self._typesense_indexer = typesense_indexer
        self._qdrant_indexer = qdrant_indexer

    async def index(self, stone_id: UUID) -> None:
        stone = await self._stone_repository.get_by_id(stone_id)
        if stone is None:
            raise LookupError(f"Stone {stone_id} was not found")

        case = await self._shelter_case_repository.get_by_stone_id(stone_id)
        if case is None:
            raise LookupError(f"Case for stone {stone_id} was not found")

        documents: list[StoneSearchDocument | CaseEventSearchDocument] = [
            build_stone_document(stone, case, stone.profile),
            *(build_case_event_document(stone, case, event) for event in case.events),
        ]
        for document in documents:
            await self._typesense_indexer.index(document)
            await self._qdrant_indexer.index(document)

"""Retrieve stone cards through lexical or vector search."""

from asyncio import TaskGroup
from typing import Final

from langchain_core.embeddings import Embeddings
from langchain_core.runnables import RunnableLambda
from qdrant_client import AsyncQdrantClient, models
from typesense import AsyncClient

from stone_shelter_assistant.search.document_models import StoneSearchDocument
from stone_shelter_assistant.search.enums import DocumentKind
from stone_shelter_assistant.search.infrastructure import qdrant_collections, typesense_collections
from stone_shelter_assistant.search.stones.rrf import fuse_stone_results
from stone_shelter_assistant.search.stones.search_contracts import (
    HybridSearchResult,
    HybridSearchSettings,
    StoneSearchFilters,
)

LEXICAL_FIELDS: Final[str] = (
    "title,text,case_number,stone_external_id,case_external_id,stone_type,stone_size,"
    "adoption_status,current_shelter_id,care_level,socialization_traits,language"
)


class StoneSearchService:
    def __init__(
        self, typesense: AsyncClient, qdrant: AsyncQdrantClient, embeddings: Embeddings
    ) -> None:
        self._typesense = typesense
        self._qdrant = qdrant
        self._embeddings = embeddings

    async def search_hybrid(
        self,
        lexical_query: str,
        semantic_query: str,
        filters: StoneSearchFilters | None = None,
        settings: HybridSearchSettings | None = None,
    ) -> HybridSearchResult:
        """Run both card searches concurrently, then fuse their complete results.

        TaskGroup cancels the sibling on failure and propagates an ExceptionGroup;
        a failed engine must not be mistaken for an empty successful result.
        """
        lexical_query, semantic_query = lexical_query.strip(), semantic_query.strip()
        if not lexical_query or not semantic_query:
            raise ValueError("Hybrid search requires both lexical and semantic queries")
        settings = HybridSearchSettings() if settings is None else settings

        async def lexical_search(_: dict[str, object]) -> list[StoneSearchDocument]:
            return await self.search_lexical(lexical_query, filters, settings.per_engine_limit)

        async def semantic_search(_: dict[str, object]) -> list[StoneSearchDocument]:
            return await self.search_semantic(semantic_query, filters, settings.per_engine_limit)

        parameters: dict[str, object] = {
            "filters": filters.model_dump(mode="json") if filters else {},
            "limit": settings.per_engine_limit,
        }
        async with TaskGroup() as group:
            lexical = group.create_task(
                RunnableLambda(lexical_search, name="typesense_search").ainvoke(
                    {**parameters, "query": lexical_query}
                )
            )
            semantic = group.create_task(
                RunnableLambda(semantic_search, name="qdrant_search").ainvoke(
                    {
                        **parameters,
                        "query": semantic_query,
                        "embedding_model": getattr(
                            self._embeddings, "model", type(self._embeddings).__name__
                        ),
                    }
                )
            )

        def fusion(_: dict[str, object]) -> HybridSearchResult:
            return fuse_stone_results(lexical.result(), semantic.result(), settings)

        return await RunnableLambda(fusion, name="rrf_fusion").ainvoke(
            {
                "lexical_ids": [str(card.id) for card in lexical.result()],
                "semantic_ids": [str(card.id) for card in semantic.result()],
                "settings": settings.model_dump(mode="json"),
            }
        )

    async def search_lexical(
        self, query: str = "", filters: StoneSearchFilters | None = None, limit: int = 5
    ) -> list[StoneSearchDocument]:
        documents = self._typesense.collections[
            typesense_collections.OPERATIONAL_COLLECTION
        ].documents
        result = await documents.search(
            {
                "q": query.strip() or "*",
                "query_by": LEXICAL_FIELDS,
                "filter_by": " && ".join(
                    f"{field}:=`{value}`" for field, value in _exact_matches(filters)
                ),
                "per_page": limit,
            }
        )
        return [
            StoneSearchDocument.model_validate(hit["document"]) for hit in result.get("hits", [])
        ]

    async def search_semantic(
        self, query: str, filters: StoneSearchFilters | None = None, limit: int = 5
    ) -> list[StoneSearchDocument]:
        query = query.strip()
        if not query:
            raise ValueError("Semantic search requires a query")
        result = await self._qdrant.query_points(
            collection_name=qdrant_collections.OPERATIONAL_COLLECTION,
            query=await self._embeddings.aembed_query(query),
            query_filter=models.Filter(
                must=[
                    models.FieldCondition(key=field, match=models.MatchValue(value=value))
                    for field, value in _exact_matches(filters)
                ]
            ),
            limit=limit,
            with_payload=True,
        )
        return [
            StoneSearchDocument.model_validate({**(point.payload or {}), "id": point.id})
            for point in result.points
        ]


def _exact_matches(filters: StoneSearchFilters | None) -> list[tuple[str, str]]:
    matches = [("document_kind", DocumentKind.STONE.value)]
    if filters is not None:
        matches.extend(
            filters.model_dump(
                mode="json", exclude_none=True, exclude={"socialization_traits"}
            ).items()
