async def test_eight_household_pairs_are_all_checked_and_rendered() -> None:
    snapshot = json.loads(
        (ROOT / "tests/fixtures/assistant/quiet-home-assessment.json").read_text()
    )
    card = next(c for c in snapshot["cards"] if c["name"] == "Sir Pebble")
    targets = [
