                    "reasons": [
                        {
                            "criterion": "quiet",
                            "evidence": [
                                {
                                    "source_id": "stone-card:internal-positive",
                                    "quote": "likes quiet",
                                }
                            ],
                        }
                    ],
                }
            ],
            "evaluation_sources": {},
            "recommended_stone_ids": ["internal-positive"],
            "result": {
                "recommended_stone_ids": ["internal-positive"],
